from datetime import date, datetime, timedelta, timezone
from pathlib import Path
import tempfile
import unittest
from unittest.mock import MagicMock, patch

import calendar_import
import config
import database
import support
import synthetic_data


START = date(2026, 11, 2)
END = date(2026, 11, 9)


def timed(*extra, uid='private-1', start='20261102T100000', end='20261102T110000'):
    """Create a fixed private appointment with optional extra ICS properties."""
    return support.calendar_event(f'UID:{uid}', f'DTSTART:{start}', f'DTEND:{end}',
                                  'SUMMARY:Private appointment', *extra)


def response(data=b'', status=200, headers=None):
    """Create a context-managed streamed response without making an HTTP request."""
    result = MagicMock()
    result.__enter__.return_value = result
    result.status_code = status
    result.headers = headers or {}
    result.is_redirect = status in (301, 302, 303, 307, 308)
    result.iter_content.return_value = [data]
    return result


class CalendarImportTests(unittest.TestCase):
    """Check recurrence, local times, private markers and exclusive calendar boundaries."""

    def parse(self, *events, **options):
        """Parse a fixed week of supplied test components."""
        return calendar_import.parse_calendar(support.calendar(*events), START, END, **options)

    def test_recurring_exdate_and_override(self):
        """Expand a daily series, exclude an exception and replace one occurrence's time."""
        base = timed('RRULE:FREQ=DAILY;COUNT=4', 'EXDATE:20261103T100000')
        replacement = timed('RECURRENCE-ID:20261104T100000',
                            start='20261104T120000', end='20261104T130000')
        blocks, _, _ = self.parse(base, replacement)
        self.assertEqual([block.start for block in blocks],
                         [datetime(2026, 11, 2, 10), datetime(2026, 11, 4, 12),
                          datetime(2026, 11, 5, 10)])

    def test_cancelled_override_suppresses_base(self):
        """A cancelled recurrence override must not resurrect the original appointment."""
        base = timed('RRULE:FREQ=DAILY;COUNT=3')
        cancelled = support.calendar_event('UID:private-1', 'STATUS:CANCELLED',
                                           'RECURRENCE-ID:20261103T100000')
        blocks, _, _ = self.parse(base, cancelled)
        self.assertEqual([block.start.day for block in blocks], [2, 4])

    def test_transparent_and_cancelled(self):
        """Ignore free reminders and cancelled events, retaining opaque appointments."""
        blocks, _, _ = self.parse(timed('TRANSP:TRANSPARENT', uid='free'),
                                  timed('STATUS:CANCELLED', uid='cancel'), timed())
        self.assertEqual(len(blocks), 1)

    def test_all_day_exclusive_end(self):
        """Label every covered date and optionally block each 07:00–23:00 window."""
        birthday = support.calendar_event('UID:birthday', 'SUMMARY:Birthday',
                                          'DTSTART;VALUE=DATE:20261105',
                                          'DTEND;VALUE=DATE:20261107')
        blocks, labels, _ = self.parse(birthday)
        self.assertEqual(blocks, [])
        self.assertEqual(labels, {date(2026, 11, 5): ['Birthday'],
                                  date(2026, 11, 6): ['Birthday']})
        blocks, busy_labels, _ = self.parse(birthday, all_day_busy=True)
        self.assertEqual(busy_labels, labels)
        self.assertEqual([block.duration_minutes() for block in blocks], [960, 960])
        self.assertEqual(blocks[0].start, datetime(2026, 11, 5, 7))

    def test_duration_and_missing_end(self):
        """Use DURATION while skipping appointments with no stated end or duration."""
        duration = support.calendar_event('UID:duration', 'DTSTART:20261102T120000',
                                          'DURATION:PT90M')
        missing = support.calendar_event('UID:missing', 'DTSTART:20261102T140000')
        all_day_missing = support.calendar_event('UID:missing-day',
                                                 'DTSTART;VALUE=DATE:20261102')
        blocks, labels, _ = self.parse(duration, missing, all_day_missing)
        self.assertEqual(len(blocks), 1)
        self.assertEqual(blocks[0].end, datetime(2026, 11, 2, 13, 30))
        self.assertEqual(labels, {})

    def test_utc_around_autumn_clock_change(self):
        """Apply Zurich's summer/winter offsets on opposite sides of 25 October 2026."""
        text = support.calendar(timed(start='20261024T080000Z', end='20261024T090000Z'),
                                timed(uid='winter', start='20261025T080000Z',
                                      end='20261025T090000Z'))
        blocks, _, _ = calendar_import.parse_calendar(text, date(2026, 10, 24), START)
        self.assertEqual([block.start.hour for block in blocks], [10, 9])
        self.assertTrue(all(block.start.tzinfo is None for block in blocks))

    def test_local_recurring_clock_stays_fixed_over_dst(self):
        """Keep weekly Zurich appointments at 09:00 across the clock change."""
        event = support.calendar_event('UID:zurich', 'RRULE:FREQ=WEEKLY;COUNT=3',
                                       'DTSTART;TZID=Europe/Zurich:20261019T090000',
                                       'DTEND;TZID=Europe/Zurich:20261019T100000')
        blocks, _, _ = calendar_import.parse_calendar(
            support.calendar(event), date(2026, 10, 19), END)
        self.assertEqual([block.start.hour for block in blocks], [9, 9, 9])

    def test_floating_and_aware_conversion(self):
        """Retain floating local time and convert aware timestamps before removing tzinfo."""
        local = datetime(2026, 11, 2, 10)
        self.assertEqual(calendar_import.to_local_naive(local), local)
        utc = datetime(2026, 11, 2, 9, tzinfo=timezone.utc)
        self.assertEqual(calendar_import.to_local_naive(utc), local)

    def test_uid_and_description_markers(self):
        """Recognize exact stable markers, rejecting malformed IDs, domains and dates."""
        valid = 'weekwise-42-20261102@weekwise'
        self.assertEqual(calendar_import.extract_weekwise_event_id(valid, ''), 42)
        self.assertEqual(calendar_import.extract_weekwise_event_id(
            'provider-id', 'Original text\nWeekWise ID: ' + valid), 42)
        for invalid in ('weekwise-42-20260230@weekwise', 'weekwise-0-20261102@weekwise',
                        'weekwise-42-20261102@other', 'weekwise-x-20261102@weekwise'):
            self.assertIsNone(calendar_import.extract_weekwise_event_id(invalid, ''))

    def test_known_and_unknown_markers(self):
        """Only deduplicate IDs rendered from the DB, keeping unknown events safely busy."""
        event = timed(uid='weekwise-42-20261102@weekwise')
        blocks, _, ids = self.parse(event)
        self.assertEqual(ids, {42})
        self.assertEqual(blocks[0].title, config.CALENDAR_UNKNOWN_EVENT_TITLE)
        self.assertEqual(self.parse(event, known_event_ids={42})[0], [])

    def test_overlap_query_boundaries(self):
        """Include overnight overlap while excluding events touching the outer bounds."""
        blocks, _, _ = self.parse(
            timed(uid='before', start='20261101T230000', end='20261102T000000'),
            timed(uid='overnight', start='20261101T230000', end='20261102T080000'),
            timed(uid='after', start='20261109T000000', end='20261109T010000'))
        self.assertEqual(len(blocks), 1)
        self.assertEqual(blocks[0].start, datetime(2026, 11, 1, 23))

    def test_invalid_calendar_and_bounds(self):
        """Reject malformed calendars and reversed ranges with ValueError."""
        with self.assertRaises(ValueError):
            calendar_import.parse_calendar('not a calendar', START, END)
        with self.assertRaises(ValueError):
            calendar_import.parse_calendar(support.calendar(), END, START)


class CalendarLoadingTests(unittest.TestCase):
    """Check network limits, fallback and explicit local remembering with isolated files."""

    def setUp(self):
        """Create temporary demo and private paths without touching application files."""
        temporary = tempfile.TemporaryDirectory()
        self.addCleanup(temporary.cleanup)
        self.directory = Path(temporary.name)
        self.demo = self.directory / 'demo.ics'
        self.upload = self.directory / 'upload.ics'
        self.link = self.directory / 'link.txt'
        self.text = support.calendar(timed())
        self.demo.write_text(self.text, encoding='utf-8')

    def load(self, mode, **options):
        """Use explicit temporary paths for every calendar-loading test."""
        return calendar_import.load_calendar(
            mode, START, END, demo_file=self.demo, private_link_file=self.link,
            private_upload_file=self.upload, **options)

    def test_webcal_and_invalid_links(self):
        """Upgrade webcal and reject insecure, malformed or fragmented URLs."""
        self.assertEqual(calendar_import.normalize_calendar_link('webcal://example.com/a.ics'),
                         'https://example.com/a.ics')
        for link in ('http://example.com/a', 'file:///a', 'https://',
                     'https://example.com/a\nB', 'https://example.com/a#fragment'):
            with self.assertRaises(ValueError):
                calendar_import.normalize_calendar_link(link)

    def test_streamed_download(self):
        """Read the body with an explicit timeout and no automatic insecure redirects."""
        fake = response(self.text.encode('utf-8'))
        with patch.object(calendar_import.requests, 'get', return_value=fake) as get:
            self.assertEqual(calendar_import.fetch_ics_text('https://example.com/a'), self.text)
        get.assert_called_once_with('https://example.com/a', timeout=config.HTTP_TIMEOUT_SECONDS,
                                    stream=True, allow_redirects=False)
        fake.__exit__.assert_called_once()

    def test_size_limits_status_and_invalid_encoding(self):
        """Enforce both advertised and streamed byte caps and reject invalid server bodies."""
        cases = [response(headers={'Content-Length': '11'}), response(b'x' * 11),
                 response(status=503), response(b'\xff'), response(b'html')]
        with patch.object(config, 'MAX_CALENDAR_BYTES', 10):
            for fake in cases:
                with patch.object(calendar_import.requests, 'get', return_value=fake):
                    with self.assertRaises(ValueError):
                        calendar_import.fetch_ics_text('https://example.com/a')

    def test_redirect_policy_and_loop_limit(self):
        """Reject HTTPS downgrade redirects and stop after the configured redirect limit."""
        downgrade = response(status=302, headers={'Location': 'http://example.com/a'})
        with patch.object(calendar_import.requests, 'get', return_value=downgrade) as get:
            with self.assertRaises(ValueError):
                calendar_import.fetch_ics_text('https://example.com/a')
            self.assertEqual(get.call_count, 1)
        loop = response(status=302, headers={'Location': '/a'})
        with patch.object(calendar_import.requests, 'get', return_value=loop) as get:
            with self.assertRaises(ValueError):
                calendar_import.fetch_ics_text('https://example.com/a')
            self.assertEqual(get.call_count, config.CALENDAR_MAX_REDIRECTS + 1)

    def test_fallback_upload_then_demo_without_secret_text(self):
        """Use remembered upload first and demo second, never exposing exception contents."""
        self.upload.write_text(self.text, encoding='utf-8')
        secret = 'https://example.com/SECRET'
        failure = calendar_import.requests.Timeout(secret)
        with patch.object(calendar_import, 'fetch_ics_text', side_effect=failure):
            result = self.load('link', link=secret)
            self.assertEqual(result[3], 'upload')
            self.assertNotIn('SECRET', result[4])
            self.upload.unlink()
            self.assertEqual(self.load('link', link=secret)[3], 'demo')

    def test_session_input_is_not_remembered(self):
        """Reading session-only upload bytes creates no private files."""
        result = self.load('upload', upload_bytes=self.text.encode('utf-8'))
        self.assertEqual(result[3], 'upload')
        self.assertFalse(self.upload.exists())
        self.assertFalse(self.link.exists())

    def test_missing_session_and_unavailable_demo(self):
        """Fall back without remembered input and report unavailable if every source fails."""
        self.assertEqual(self.load('link')[3], 'demo')
        self.demo.unlink()
        result = self.load('upload', upload_bytes=b'broken')
        self.assertEqual(result[:4], ([], {}, set(), 'unavailable'))
        self.assertIn('unavailable', result[4])

    def test_remember_and_forget(self):
        """Write only opted-in files and forget only those files."""
        sibling = self.directory / 'keep.txt'
        sibling.write_text('keep', encoding='utf-8')
        with patch.multiple(config, PRIVATE_DIR=self.directory,
                            PRIVATE_CALENDAR_LINK_FILE=self.link,
                            PRIVATE_CALENDAR_UPLOAD_FILE=self.upload):
            calendar_import.remember_calendar('link', 'webcal://example.com/calendar')
            calendar_import.remember_calendar('upload', upload_bytes=self.text.encode('utf-8'))
            self.assertEqual(self.link.read_text(), 'https://example.com/calendar')
            self.assertEqual(self.load('upload')[3], 'upload')
            calendar_import.forget_calendar()
        self.assertFalse(self.link.exists())
        self.assertFalse(self.upload.exists())
        self.assertTrue(sibling.exists())


class DemoCalendarTests(support.DatabaseCase):
    """Verify the specification's demo calendar and a safe upgrade from M1 data."""

    def test_demo_week(self):
        """Render fourteen weekly blocks, one party and Thursday's all-day birthday."""
        path = self.directory / 'demo.ics'
        synthetic_data.write_demo_calendar(START, path)
        blocks, labels, _ = calendar_import.parse_calendar(path.read_text(), START, END)
        self.assertEqual(len(blocks), 15)
        self.assertEqual(labels, {date(2026, 11, 5): ["Mum's birthday"]})
        self.assertNotIn('Transparent reminder', [block.title for block in blocks])
        week_two, _, _ = calendar_import.parse_calendar(
            path.read_text(), END, END + timedelta(days=7))
        self.assertIn('Dentist', [block.title for block in week_two])

    def test_m1_upgrade_preserves_data_and_anchor(self):
        """Create a missing calendar from the saved demo anchor without resetting events."""
        self.save()
        database.set_setting(self.connection, 'demo_anchor_date', START.isoformat())
        path = self.directory / 'demo.ics'
        synthetic_data.ensure_demo_calendar(self.connection, path, now=support.NOW)
        before = path.read_bytes()
        synthetic_data.ensure_demo_calendar(self.connection, path, now=support.NOW)
        self.assertEqual(path.read_bytes(), before)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM events'), 1)
